  "app.setBooking.travelHint": "ਕਲਾਇੰਟ ਵਿਜ਼ਿਟ ਬੁੱਕ ਕਰਨ ਵੇਲੇ ਪਤਾ ਦਿੰਦੇ ਹਨ। ਉਹ ਸਮੇਂ ਜਿੱਥੇ ਤੁਸੀਂ ਆਪਣੇ ਪਿਛਲੇ ਕੰਮ ਤੋਂ ਸਮੇਂ ਸਿਰ ਨਹੀਂ ਪਹੁੰਚ ਸਕਦੇ, ਲੁਕਾ ਦਿੱਤੇ ਜਾਂਦੇ ਹਨ।",
